export function createFlightGameHost({getContext,setRoom,isAllowed,clearInput,stopLocomotion,onChange=()=>{},onFatal=()=>{},openMap,getMood,reduced=false}){
 const initial=getContext(),{scene,player,model,poser,cam,camera,stage}=initial,doc=stage.ownerDocument??globalThis.document;let controls=null,disposed=false,choice=0,lastPromise=null,qualityContinuous=false,qualityPaused=false,frameFailure=null;
 const neutralize=()=>{clearInput();stopLocomotion();},presentation=createFlightPresentation({scene,player,model,poser,sourceCamera:camera,getMood,reduced,getViewport:()=>({width:stage.clientWidth,height:stage.clientHeight}),clearInput:neutralize}),settlement=createFlightHostSettlement({getView:()=>getContext().view,getRoom:()=>getContext().room,setRoom,scene,player,model,poser,cam,camera,stage,clearInput,stopLocomotion,syncRoom:()=>getContext().sync(),document:doc});
 const controller=createFlightController({transition:(...a)=>getContext().manager.transitionTo(...a),cancelTransition:()=>getContext().manager.cancel(),getManagerToken:()=>getContext().manager.token,getManagerPhase:()=>getContext().manager.phase,getView:()=>getContext().view,presentation,isAllowed:()=>!disposed&&isAllowed(),clearInput:neutralize,prepareCommit:settlement.prepare,captureCommit:settlement.captureCommitted,settleCommitError:settlement.settle,isCommitSettled:settlement.probe,getSettlementResult:()=>getContext().manager.lastSettlement,reduced,document:doc,window:doc.defaultView??globalThis.window,openMap,notice:text=>getContext().ui.toast(text),onFatal,onChange(){const paused=controller.snapshot()?.paused??false;if(paused!==qualityPaused){qualityContinuous=false;qualityPaused=paused;}if(controller.active&&!controls)controls=mountFlightControls({stage,controller});if(!controller.active&&controls){controls.dispose();controls=null;if(!controller.blocked)settlement.clear();}controls?.sync();onChange();}});
 function valid(target,route){try{if(!route||target?.id!==route.from.target.id)return false;const c=getContext(),e=route.from,resolved=resolveLocation({roomId:e.roomId,spawnId:e.spawnId}),expected=resolved?.runtimeRoom,local=airportLocalPoint(c.view,scene,e,player.position);if(!resolved||resolved.endpointId&&!c.view.endpointContext?.(e.roomId)||c.room!==expected||c.manager.current!==c.view||c.view.root.parent!==scene||Math.hypot(local.x-e.target.at.x,local.z-e.target.at.z)>e.target.radius+1e-8)return false;c.view.prepareEndpoint?.(e.roomId);const context=airportEndpointContext(c.view,e),world=airportEndpointWorld(c.view,scene,e),global=c.view.endpointContext?.(e.roomId)?c.view.collisionWorld?.()??c.view.residents?.collisionWorld?.()??c.room:null,at=airportScenePoint(c.view,scene,e,e.target.at);return !!context.airport?.ready&&canMove(world,local.x,local.z,.66)&&lineClear(world,local,e.target.at,.66)&&(!global||canMove(global,player.position.x,player.position.z,.66)&&lineClear(global,player.position,at,.66));}catch{return false;}}

 function open(target){if(disposed||frameFailure||controller.active||controller.blocked||!isAllowed())return false;const c=getContext(),endpointId=Object.values(FLIGHT_ENDPOINTS).find(e=>e.target.id===target?.id)?.roomId,route=flightRouteFrom(endpointId);if(!valid(target,route)){c.ui.toast('탑승 표시 앞으로 걸어와 주세요');return false;}neutralize();const origin=c.view,token=++choice;let chosen=false;const modes=reduced?['free','animated']:['animated','free'],labels={animated:'비행기 타고 가기',free:'움직임 없이 이동'};
  return c.ui.workshop(route.to.label+'으로',`<p>비행기에 올라 하늘을 날거나, 움직임 없이 바로 갈 수 있어요.</p><div class="flight-mode-choices">${modes.map((mode,i)=>`<button type="button" data-flight-mode="${mode}"${i===0?' autofocus':''}>${labels[mode]}</button>`).join('')}</div>`,()=>{const buttons=[...doc.querySelectorAll('[data-flight-mode]')];for(const button of buttons)button.onclick=()=>{if(chosen||disposed||choice!==token)return;chosen=true;c.ui.switchTo(()=>{if(disposed||choice!==token||getContext().view!==origin||!isAllowed()||!valid(target,route))return;choice++;neutralize();lastPromise=controller.start(route,{motionFree:button.dataset.flightMode==='free'});});};return()=>{for(const button of buttons)button.onclick=null;if(!chosen&&choice===token)choice++;};},{kind:'flight-choice',closeLabel:'그대로 있기'});
 }
 return{open,failFrame(error){if(frameFailure)return;frameFailure=error;qualityContinuous=false;try{controller.retire('frame-failure');}catch{}finally{try{onFatal({reason:'Flight frame failed',error});}catch{}}},consumeFrameContinuity(){const valid=qualityContinuous;qualityContinuous=true;return valid;},tick(dt){controller.tick(dt);controls?.sync();},fit(width,height){const visible=presentation.fit(width,height,{padding:readFlightSafeArea(stage)});controls?.setCover(presentation.coverOpacity);getContext().view?.updateVisibility?.(visible??camera,player.position);return visible;},pause:()=>controller.pause(),resume:()=>controller.resume(),cancelOrSkip:()=>controller.cancelOrSkip(),requestMap:()=>controller.requestMap(),retire:reason=>{choice++;return controller.retire(reason);},resize(){controller.resize();if(controller.snapshot()?.committed)settlement.captureCommitted(getContext().view);controls?.sync();},get active(){return controller.active;},get blocked(){return !!frameFailure||controller.blocked;},get disposed(){return disposed;},get completion(){return lastPromise;},snapshot:()=>({trip:controller.snapshot(),presentation:presentation.snapshot(),settlement:settlement.snapshot(),blocked:!!frameFailure||controller.blocked,frameFailure:frameFailure?String(frameFailure.message??frameFailure):null,disposed}),dispose(){if(disposed)return;disposed=true;choice++;controller.dispose();controls?.dispose();controls=null;presentation.dispose();}};
}
export function renderFlightGameFrame({flight,renderer,scene,camera,stage,player,sun,dt,ms=dt*1000,sampleFrame=()=>{},document:doc=globalThis.document}){try{flight.tick(dt);const trip=flight.snapshot().trip,eligible=!!trip&&trip.ready&&!trip.paused&&!trip.motionFree&&!flight.blocked&&!doc?.hidden&&['boarding','cancelling','reopening','seal','taxi-out','takeoff-roll','climb','cruise','approach','landing-roll','taxi-in','open','dismount'].includes(trip.phase);const continuous=flight.consumeFrameContinuity();sampleFrame(ms,eligible&&continuous);if(doc?.hidden)return;const visible=flight.fit(stage.clientWidth,stage.clientHeight)??camera;sun.position.set(player.position.x-3,player.position.y+9,player.position.z+7);sun.target.position.copy(player.position);sun.target.updateMatrixWorld();renderer.setScissorTest(false);renderer.setViewport(0,0,stage.clientWidth,stage.clientHeight);renderer.render(scene,visible);}catch(error){flight.failFrame(error);}}
